from __future__ import annotations

import base64
from hashlib import sha256
from pathlib import Path
import subprocess
import zlib

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "PrimalitySheafVerification" / "Mock2_FunctionalAnalysis.lean"
EXPECTED_INPUT_SHA256 = "31f3ecaf1d42e21e630de3f693f35f459500eec4c320771b919414b3de7154b7"
EXPECTED_OUTPUT_SHA256 = "5ab144401a2798e13e52c9cd7a359ace82a7f8c97d28351a4a48ae14d5e1f19e"
PATCH_ZLIB_BASE64 = ""


def file_sha256(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def main() -> int:
    before = file_sha256(TARGET)
    print(f"input_sha256={before}")
    if before == EXPECTED_OUTPUT_SHA256:
        print("[pass361] already applied")
        return 0
    if before != EXPECTED_INPUT_SHA256:
        raise RuntimeError(
            f"unexpected pass361 input sha256: {before}; expected {EXPECTED_INPUT_SHA256}"
        )
    patch = zlib.decompress(base64.b64decode(PATCH_ZLIB_BASE64))
    subprocess.run(
        ["git", "apply", "--whitespace=nowarn", "-"],
        cwd=ROOT,
        input=patch,
        check=True,
    )
    after = file_sha256(TARGET)
    print(f"output_sha256={after}")
    if after != EXPECTED_OUTPUT_SHA256:
        raise RuntimeError(
            f"unexpected pass361 output sha256: {after}; expected {EXPECTED_OUTPUT_SHA256}"
        )
    print("[pass361] FunctionalAnalysis covariance, transport, Green, tile, and curved-chart roots repaired")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
